<div class="admin-metrics admin-fund-metrics">
<article class="admin-metric"><div class="admin-metric-caption">Thành viên tham gia <?= $adminIcon('members') ?></div><strong><?= (int)$fundSummary['participants'] ?></strong><small>Tự nguyện · <?= sf_h(date('m/Y',strtotime($fund['month_start']))) ?></small></article>
<article class="admin-metric"><div class="admin-metric-caption">Đã xác nhận đóng <?= $adminIcon('check') ?></div><strong><?= (int)$fundSummary['paid_count'] ?></strong><small><?= (int)$fundSummary['participants']-(int)$fundSummary['paid_count'] ?> người chưa xác nhận</small></article>
<article class="admin-metric"><div class="admin-metric-caption">Số quỹ ghi nhận <?= $adminIcon('fund') ?></div><strong><?= number_format((int)$fundSummary['recorded_total'],0,',','.') ?> ₫</strong><small>Tổng khoản đóng và phạt đã ghi sổ</small></article>
</div>
<section class="panel"><div class="section-heading"><div><h2>Thành viên và xác nhận quỹ</h2><p>Admin xác nhận tham gia và ghi nhận đã đóng quỹ</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Thành viên</th><th>Kỳ tháng</th><th>Mức đóng</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>
<?php foreach ($adminFundMembers as $member): ?><tr><td><div class="admin-person"><span class="admin-initial"><?= sf_h(mb_substr($member['display_name'],0,1,'UTF-8')) ?></span><b><?= sf_h($member['display_name']) ?></b></div></td><td><?= sf_h(date('m/Y',strtotime($fund['month_start']))) ?></td><td><?= number_format((int)$fund['contribution_amount'],0,',','.') ?> ₫</td><td><span class="admin-status <?= $member['contribution_status']==='paid'?'':'wait' ?>"><?= $member['contribution_status']==='paid'?'Đã xác nhận':'Chưa xác nhận' ?></span></td><td><?php if ($canManageFund && $member['contribution_status']!=='paid'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="fund_mark_paid"><input type="hidden" name="return_to" value="admin"><input type="hidden" name="member_id" value="<?= (int)$member['user_id'] ?>"><button class="btn secondary">Xác nhận tham gia &amp; đã đóng quỹ</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?>
<?php if (!$adminFundMembers): ?><tr><td colspan="5" class="admin-empty">Chưa có thành viên tham gia quỹ tháng này.</td></tr><?php endif; ?>
</tbody></table></div></section>
<?php if ($canManageFund): ?><section class="panel"><div class="section-heading"><div><h2>Ghi sổ giao dịch</h2><p>Ghi nhận khoản đóng góp, phạt hoặc thưởng</p></div></div><form method="post" class="admin-inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="admin_fund_transaction"><input type="hidden" name="fund_id" value="<?= (int)$fund['id'] ?>"><select name="member_id" required aria-label="Thành viên giao dịch"><?php foreach ($adminActionMembers as $member): ?><option value="<?= (int)$member['id'] ?>"><?= sf_h($member['display_name']) ?></option><?php endforeach; ?></select><select name="transaction_type" aria-label="Loại giao dịch"><option value="contribution">Đóng góp</option><option value="penalty">Phạt</option><option value="reward">Thưởng</option></select><input name="amount" type="number" min="1" max="100000000" required placeholder="Số tiền (đồng)" aria-label="Số tiền"><input name="note" minlength="3" maxlength="255" required placeholder="Ghi chú" aria-label="Ghi chú giao dịch"><button class="btn primary">Ghi sổ</button></form></section><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h2>Lịch sử giao dịch</h2><p>Các khoản đã được ghi nhận trong tháng</p></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Thành viên</th><th>Loại</th><th>Số tiền</th><th>Thời gian</th><th>Ghi chú</th></tr></thead><tbody><?php $transactionLabels=['contribution'=>'Đóng góp','penalty'=>'Phạt','reward'=>'Thưởng']; foreach ($adminFundTransactions as $transaction): ?><tr><td><?= sf_h($transaction['display_name']) ?></td><td><?= sf_h($transactionLabels[$transaction['transaction_type']]??$transaction['transaction_type']) ?></td><td><?= number_format((int)$transaction['amount'],0,',','.') ?> ₫</td><td><?= sf_h(sf_format_time($transaction['created_at'],'d/m · H:i')) ?></td><td><?= sf_h($transaction['note']) ?></td></tr><?php endforeach; ?><?php if (!$adminFundTransactions): ?><tr><td colspan="5" class="admin-empty">Chưa có giao dịch nào.</td></tr><?php endif; ?></tbody></table></div></section>
<?php if ($canManageFund): ?><section class="panel"><div class="section-heading"><div><h2>Biểu quyết mức phạt</h2><p>Mở biểu quyết khi có đề xuất, chốt kết quả khi đã có phiếu</p></div></div><?php foreach ($fundProposals as $proposal): ?><div class="admin-member-row"><span><?= sf_h($proposal['display_name']) ?></span><b><?= number_format((int)$proposal['amount']) ?> ₫</b></div><?php endforeach; ?>
<?php if ($fund['status']==='closed'): ?><p class="final-penalty">Mức phạt đã chốt: <b><?= number_format((int)$fund['final_penalty']) ?> ₫</b></p>
<?php elseif ($fund['status']==='voting' || $fundProposals): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="return_to" value="admin"><input type="hidden" name="action" value="<?= $fund['status']==='voting'?'fund_close_vote':'fund_start_vote' ?>"><button class="btn secondary"><?= $fund['status']==='voting'?'Chốt biểu quyết':'Mở biểu quyết' ?></button></form>
<?php else: ?><p class="admin-empty">Chưa có đề xuất mức phạt tháng này.</p><?php endif; ?></section><?php endif; ?>
